theorem rmsNormGeneral_sharp_recovers_rmsNormE {n : ℕ}
    (x : EuclideanSpace ℝ (Fin n)) (c : ℝ) (hc : 0 < c) (hx : ‖x‖ = c) :
    ‖rmsNormE x - rmsNormE (-x)‖ = (Real.sqrt n / c) * ‖x - (-x)‖

theorem ssd_prod_concat (A : ℕ → Matrix (Fin n) (Fin n) ℝ) {i m j : ℕ}
    (him : i < m) (hmj : m ≤ j) :
    selProd A (i + 1) j = selProd A m j * selProd A (i + 1) m
